style.css:
@-moz-document domain("youtube.com") {
/* --- 1. THE LIVE BACKGROUND (Fixed & Reliable) --- */
    /* This sets the raining city loop as the foundation */
    html, [dark], ytd-app, #master-container {
        /* Direct link to a seamless Lofi Rain Loop */
        background: url("https://media2.giphy.com/media/v1.Y2lkPTc5MGI3NjExeTQ0ZGIwd295ZTkzbXJoYWxjcXF3M2liaTg1eWswdXl4N3RuZDI4NCZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/RgZFvGuI4OxLjuSvRF/giphy.gif") no-repeat center center fixed !important;
        background-size: cover !important;
        
        /* Make standard backgrounds invisible so the GIF shows */
        -yt-spec-base-background: transparent !important;
        -yt-spec-brand-background-primary: transparent !important;
        -yt-spec-raised-background: transparent !important; 
        -yt-spec-menu-background: rgba(20, 20, 35, 0.9) !important;
        -yt-spec-text-primary: #fff !important;
    }

    /* --- 2. GLOBAL DARK OVERLAY (Vibe Control) --- */
    /* Adds a dark tint so you can read text over the bright GIF */
    ytd-app::before {
        content: "";
        position: fixed;
        top: 0; left: 0; width: 100%; height: 100%;
        background: rgba(10, 10, 20, 0.75); /* Adjust opacity (0.75) to make it darker/lighter */
        z-index: -1;
        pointer-events: none;
    }

    /* --- 3. TRUE GLASSMORPHISM (The "Smooth" Look) --- */
    /* Header, Sidebar, and Guide - Frosted Glass Effect */
    #masthead-container, ytd-mini-guide-renderer, #guide-content {
        background: rgba(20, 20, 30, 0.4) !important; /* Semi-transparent */
        backdrop-filter: blur(12px) !important; /* BLURS the rain behind it */
        border-bottom: 1px solid rgba(255, 255, 255, 0.08);
        box-shadow: 0 4px 30px rgba(0, 0, 0, 0.3);
    }

    /* --- 4. LIQUID BUTTONS & CHIPS --- */
    /* Rounded "Pill" Shapes */
    yt-button-shape, button.yt-spec-button-shape-next, yt-chip-cloud-chip-renderer {
        background: rgba(255, 255, 255, 0.05) !important;
        border: 1px solid rgba(255, 255, 255, 0.1) !important;
        border-radius: 50px !important;
        color: #ddd !important;
        transition: all 0.4s cubic-bezier(0.25, 0.8, 0.25, 1) !important; /* Smooth physics */
    }

    /* Hover: Glows Purple/Pink */
    yt-button-shape:hover, button.yt-spec-button-shape-next:hover, yt-chip-cloud-chip-renderer:hover {
        background: rgba(180, 130, 255, 0.2) !important;
        border-color: #b482ff !important;
        box-shadow: 0 0 15px rgba(180, 130, 255, 0.4);
        transform: translateY(-2px);
        color: #fff !important;
    }

    /* Selected Chip (e.g. "All") */
    yt-chip-cloud-chip-renderer[selected] {
        background: #b482ff !important;
        color: #1a1a1a !important;
        font-weight: bold;
        box-shadow: 0 0 20px #b482ff;
        border: none !important;
    }

    /* --- 5. SEARCH BAR (Floating) --- */
    #search-form #container {
        background: rgba(0, 0, 0, 0.5) !important;
        border: 1px solid rgba(255, 255, 255, 0.1) !important;
        border-radius: 30px !important;
    }
    #search-form #container:focus-within {
        border-color: #b482ff !important;
        box-shadow: 0 0 15px rgba(180, 130, 255, 0.3);
    }

    /* --- 6. VIDEO PLAYER (Vibe Aroma) --- */
    /* Progress Bar: Purple to Pink Gradient */
    .ytp-play-progress {
        background: linear-gradient(90deg, #82b1ff, #b482ff, #ff8fab) !important;
        box-shadow: 0 0 15px #b482ff;
    }
    
    /* The Scrubber Dot */
    .ytp-scrubber-button {
        background: #fff !important;
        box-shadow: 0 0 10px #fff, 0 0 20px #ff8fab;
        transform: scale(1.3);
    }
    
    /* Make the player controls background darker for visibility */
    .ytp-gradient-bottom {
        background: linear-gradient(to top, rgba(0,0,0,0.9), transparent) !important;
    }

    /* --- 7. THUMBNAILS (Soft Corners) --- */
    ytd-thumbnail {
        border-radius: 12px !important;
        box-shadow: 0 4px 10px rgba(0,0,0,0.5);
        transition: 0.3s;
    }
    ytd-rich-item-renderer:hover ytd-thumbnail {
        box-shadow: 0 0 25px rgba(180, 130, 255, 0.3); /* Purple Glow on Hover */
        transform: scale(1.02);
    }
}
